// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank, Log} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        amount = bound(amount, 1 ether, 10000 ether);
        vm.deal(actor, amount);
        uint256 before = c.balances(actor);
        vm.prank(actor);
        c.Deposit{value: amount}();
        // General rule: depositing `amount` (>= MinDeposit) increases the
        // sender's recorded balance by exactly `amount` (> 1).
        assertTrue(c.balances(actor) - before == amount);
    }
}
